import CryptoKit
import Foundation
import Testing
@testable import PulseKit

/// Cross-checks the Swift implementation against `docs/protocol-vectors.json` (generated by the Rust crate).
/// Override the location with `UWUPULSE_VECTORS=/path/to/file.json`.
///
/// The loader is tolerant about field names (snake_case/camelCase, nesting) so it does not have to
/// change in lockstep with the generator; it fails with the list of keys it saw if something is missing.
@Suite struct ProtocolVectorTests {
    static var vectorsURL: URL {
        if let override = ProcessInfo.processInfo.environment["UWUPULSE_VECTORS"] {
            return URL(fileURLWithPath: override)
        }
        // apple/PulseKit/Tests/PulseKitTests/<file> → repo root
        return URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("docs/protocol-vectors.json")
    }

    static func loadRoot() throws -> [String: Any]? {
        let url = vectorsURL
        guard FileManager.default.fileExists(atPath: url.path) else {
            Issue.record("protocol vectors missing at \(url.path) — generate them with the Rust crate (uwupulse-proto) first")
            return nil
        }
        return try JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any]
    }

    /// 0x2A37 parser: same results as the Rust parser, including rejected inputs.
    @Test func heartRateMeasurementVectors() throws {
        guard let root = try Self.loadRoot(), let cases = root["heart_rate_measurement"] as? [[String: Any]] else {
            if FileManager.default.fileExists(atPath: Self.vectorsURL.path) { Issue.record("heart_rate_measurement missing") }
            return
        }
        for c in cases {
            let input = try #require((c["input"] as? String).flatMap { Data(hex: $0) })
            let parsed = HeartRateMeasurement(data: input)
            if c["invalid"] as? Bool == true {
                #expect(parsed == nil, "\(c["input"]!): should be rejected")
                continue
            }
            let m = try #require(parsed, "\(c["input"]!): should parse")
            #expect(m.bpm == c["bpm"] as? Int)
            #expect(m.sensorContact == c["contact"] as? Bool)
            #expect(m.energyExpended == c["energy_kj"] as? Int)
            #expect(m.rrIntervals == (c["rr_ms"] as? [Int] ?? []))
        }
    }

    @Test func pairingURIVector() throws {
        guard let root = try Self.loadRoot(), let v = root["pairing_uri"] as? [String: Any] else {
            if FileManager.default.fileExists(atPath: Self.vectorsURL.path) { Issue.record("pairing_uri missing") }
            return
        }
        let uri = try #require(v["uri"] as? String)
        let vectorHosts = v["hosts"] as? [String] ?? []
        // The desktop only puts local-network hosts into the code, and the phone only accepts those.
        #expect(vectorHosts.allSatisfy(PairingOffer.isAllowedHost))
        let offer = try PairingOffer(uri: uri)
        #expect(offer.desktopId == v["id"] as? String)
        #expect(offer.name == v["name"] as? String)
        #expect(offer.publicKey == (v["pk"] as? String).flatMap { Data(hex: $0) })
        #expect(offer.secret == (v["secret"] as? String).flatMap { Data(hex: $0) })
        #expect(offer.port == v["port"] as? Int)
        #expect(offer.hosts == v["hosts"] as? [String])
    }

    @Test func rustVectors() throws {
        let url = Self.vectorsURL
        guard FileManager.default.fileExists(atPath: url.path) else {
            Issue.record("protocol vectors missing at \(url.path) — generate them with the Rust crate (uwupulse-proto) first")
            return
        }
        let root = try JSONSerialization.jsonObject(with: Data(contentsOf: url))
        let cases = Vectors.handshakeCases(in: root)
        try #require(!cases.isEmpty, "no handshake case (object with an \"m1\" field) found in \(url.lastPathComponent)")

        var frameCount = 0
        for (index, raw) in cases.enumerated() {
            let c = Vectors.Case(raw)
            let label = "case \(index)"
            let m1 = try c.string(["m1"], label)
            let m2 = try c.string(["m2"], label)
            let phoneS = try c.privateKey(role: .phone, kind: .static, label)
            let phoneE = try c.privateKey(role: .phone, kind: .ephemeral, label)
            let deskS = try c.privateKey(role: .desk, kind: .static, label)
            let deskE = try c.privateKey(role: .desk, kind: .ephemeral, label)
            let psk = c.bytes(["psk"]) ?? LinkProtocol.zeroPSK

            // m1/m2 must carry the public keys of the given private keys (b64 interop).
            guard case .hello(let h1) = try LinkMessage.decode(Data(m1.utf8)),
                  case .hello(let h2) = try LinkMessage.decode(Data(m2.utf8))
            else { Issue.record("\(label): m1/m2 are not hello messages"); continue }
            #expect(B64.decode(h1.spk) == phoneS.publicKey.rawRepresentation, "\(label): m1.spk")
            #expect(h2.epk.flatMap(B64.decode) == deskE.publicKey.rawRepresentation, "\(label): m2.epk")
            #expect(B64.decode(h2.spk) == deskS.publicKey.rawRepresentation, "\(label): m2.spk")

            // sas: m1 carries only the commitment, m3 reveals epk. known/qr: epk in m1, no m3.
            let commitField = c.value(["commit"]) as? String
            let m3 = c.value(["m3"]) as? String
            let phoneEpk = phoneE.publicKey.rawRepresentation
            if h1.mode == .sas {
                #expect(h1.epk == nil, "\(label): sas m1 must not contain epk")
                let commit = LinkKeySchedule.commitment(ephemeralPublicKey: phoneEpk)
                #expect(h1.commit.flatMap(B64.decode) == commit, "\(label): m1.commit")
                #expect(commitField.flatMap(B64.decode) == commit, "\(label): commit field")
                let m3Text = try #require(m3, "\(label): sas case without m3 (keys: \(c.keys))")
                guard case .reveal(let revealed) = try LinkMessage.decode(Data(m3Text.utf8)) else {
                    Issue.record("\(label): m3 is not a reveal message"); continue
                }
                #expect(B64.decode(revealed) == phoneEpk, "\(label): m3.epk")
            } else {
                #expect(h1.epk.flatMap(B64.decode) == phoneEpk, "\(label): m1.epk")
                #expect(h1.commit == nil && commitField == nil && m3 == nil, "\(label): commit/m3 only in sas")
            }
            let m3Bytes = h1.mode == .sas ? m3.map { Data($0.utf8) } : nil

            let phoneKeys = try LinkKeySchedule.derive(
                ownStatic: phoneS, ownEphemeral: phoneE, peerStatic: deskS.publicKey, peerEphemeral: deskE.publicKey,
                psk: psk, m1: Data(m1.utf8), m2: Data(m2.utf8), m3: m3Bytes
            )
            let deskKeys = try LinkKeySchedule.derive(
                ownStatic: deskS, ownEphemeral: deskE, peerStatic: phoneS.publicKey, peerEphemeral: phoneE.publicKey,
                psk: psk, m1: Data(m1.utf8), m2: Data(m2.utf8), m3: m3Bytes
            )
            #expect(phoneKeys == deskKeys, "\(label): roles disagree")

            if let th = c.bytes(["th"], ["transcript"]) { #expect(phoneKeys.transcriptHash == th, "\(label): th") }
            else { Issue.record("\(label): th missing (keys: \(c.keys))") }
            if let k = c.bytes(["p2d"]) { #expect(phoneKeys.phoneToDesktop.raw == k, "\(label): k_p2d") }
            else { Issue.record("\(label): k_p2d missing (keys: \(c.keys))") }
            if let k = c.bytes(["d2p"]) { #expect(phoneKeys.desktopToPhone.raw == k, "\(label): k_d2p") }
            else { Issue.record("\(label): k_d2p missing (keys: \(c.keys))") }
            if let sas = c.scalar(["sas"]) { #expect(phoneKeys.sas == Vectors.sasString(sas), "\(label): sas") }
            else { Issue.record("\(label): sas missing (keys: \(c.keys))") }

            // Sealed frames: either inside the case or at top level (then they belong to the first case).
            var frames = Vectors.frames(in: raw)
            if frames.isEmpty, index == 0 { frames = Vectors.frames(in: root, topLevelOnly: true) }
            for (fi, frame) in frames.enumerated() {
                let fl = "\(label) frame \(fi)"
                let toDesktop = frame.toDesktop
                let key = toDesktop ? phoneKeys.phoneToDesktop : phoneKeys.desktopToPhone
                var opener = FrameCipher(key: key, counter: frame.counter)
                let opened = try opener.open(frame.sealed)
                if let pt = frame.plaintextBytes {
                    #expect(opened == pt, "\(fl): plaintext")
                    var sealer = FrameCipher(key: key, counter: frame.counter)
                    #expect(try sealer.seal(pt) == frame.sealed, "\(fl): sealed bytes")
                } else if let obj = frame.plaintextObject {
                    let parsed = try JSONSerialization.jsonObject(with: opened)
                    #expect((parsed as AnyObject).isEqual(obj), "\(fl): plaintext JSON")
                }
                frameCount += 1
            }
        }
        #expect(frameCount > 0, "no sealed frames found in vectors")
    }
}

private extension SymmetricKey {
    var raw: Data { withUnsafeBytes { Data($0) } }
}

/// Tolerant accessors for the vector JSON.
enum Vectors {
    enum Role { case phone, desk }
    enum Kind { case `static`, ephemeral }

    static func handshakeCases(in any: Any) -> [[String: Any]] {
        if let dict = any as? [String: Any] {
            if dict["m1"] is String { return [dict] }
            return dict.keys.sorted().flatMap { handshakeCases(in: dict[$0]!) }
        }
        if let array = any as? [Any] { return array.flatMap { handshakeCases(in: $0) } }
        return []
    }

    /// Splits `phoneStatic_sk` / `phone.static.sk` into lowercase tokens.
    static func tokens(_ path: String) -> [String] {
        var out: [String] = []
        var current = ""
        var previousLower = false
        for ch in path {
            if ch == "_" || ch == "." || ch == "-" || ch == " " {
                if !current.isEmpty { out.append(current) }
                current = ""; previousLower = false
            } else if ch.isUppercase, previousLower {
                out.append(current); current = String(ch).lowercased(); previousLower = false
            } else {
                current += ch.lowercased(); previousLower = ch.isLowercase || ch.isNumber
            }
        }
        if !current.isEmpty { out.append(current) }
        return out
    }

    /// Flattens nested objects to dotted paths (arrays are skipped).
    static func flatten(_ dict: [String: Any], prefix: String = "") -> [String: Any] {
        var out: [String: Any] = [:]
        for (k, v) in dict {
            let path = prefix.isEmpty ? k : "\(prefix).\(k)"
            if let nested = v as? [String: Any] { out.merge(flatten(nested, prefix: path)) { a, _ in a } }
            else if !(v is [Any]) { out[path] = v }
        }
        return out
    }

    static func bytes(from value: Any) -> Data? {
        guard let s = value as? String else { return nil }
        if let hex = Data(hex: s), !s.isEmpty { return hex }
        if let b = B64.decode(s) { return b }
        return Data(base64Encoded: s)
    }

    static func sasString(_ value: Any) -> String {
        if let n = value as? NSNumber { return LinkKeySchedule.formatSAS(n.uint32Value) }
        return "\(value)"
    }

    struct Case {
        let flat: [String: Any]
        init(_ raw: [String: Any]) { flat = Vectors.flatten(raw) }
        var keys: [String] { flat.keys.sorted() }

        /// First value whose token list contains all tokens of any of the alternatives.
        func value(_ alternatives: [String]...) -> Any? {
            for alt in alternatives {
                for key in keys where Set(Vectors.tokens(key)).isSuperset(of: alt) { return flat[key] }
            }
            return nil
        }

        func string(_ alt: [String], _ label: String) throws -> String {
            guard let s = value(alt) as? String else {
                throw VectorError("\(label): \(alt) missing (keys: \(keys))")
            }
            return s
        }

        func bytes(_ alternatives: [String]...) -> Data? {
            for alt in alternatives { if let v = value(alt), let d = Vectors.bytes(from: v) { return d } }
            return nil
        }

        func scalar(_ alt: [String]) -> Any? { value(alt) }

        func privateKey(role: Role, kind: Kind, _ label: String) throws -> Curve25519.KeyAgreement.PrivateKey {
            let roleTokens: Set<String> = role == .phone ? ["phone", "iphone", "p", "initiator"] : ["desk", "desktop", "d", "responder"]
            let kindTokens: Set<String> = kind == .static ? ["static", "s", "stat"] : ["ephemeral", "eph", "e"]
            let privTokens: Set<String> = ["sk", "priv", "private", "secret", "seed", "privkey"]
            let compact: Set<String> = kind == .static ? ["ssk", "spriv", "staticsk", "staticpriv"] : ["esk", "epriv", "ephsk", "ephpriv"]
            // Pass 1 needs an explicit "private" token; pass 2 accepts e.g. `s_phone` (spec notation).
            for strict in [true, false] {
                for key in keys {
                    let t = Set(Vectors.tokens(key))
                    guard !t.isDisjoint(with: roleTokens), t.isDisjoint(with: ["pub", "pk", "public", "spk", "epk", "shared", "dh"]) else { continue }
                    let hasKind = !t.isDisjoint(with: kindTokens)
                    let kindMatch = strict ? (hasKind && !t.isDisjoint(with: privTokens) || !t.isDisjoint(with: compact)) : hasKind
                    guard kindMatch, let v = flat[key], let raw = Vectors.bytes(from: v), raw.count == 32 else { continue }
                    return try .init(rawRepresentation: raw)
                }
            }
            throw VectorError("\(label): \(role) \(kind) private key missing (keys: \(keys))")
        }
    }

    struct Frame {
        var toDesktop: Bool
        var counter: UInt64
        var sealed: Data
        var plaintextBytes: Data?
        var plaintextObject: Any?
    }

    static func frames(in any: Any, topLevelOnly: Bool = false) -> [Frame] {
        var out: [Frame] = []
        func visit(_ value: Any, path: [String], depth: Int) {
            if let array = value as? [Any] {
                for item in array {
                    if let dict = item as? [String: Any], let f = frame(dict, path: path) { out.append(f) }
                    else if !topLevelOnly { visit(item, path: path, depth: depth + 1) }
                }
            } else if let dict = value as? [String: Any], depth == 0 || !topLevelOnly {
                for (k, v) in dict where !(depth > 0 && v is String) { visit(v, path: path + [k], depth: depth + 1) }
            }
        }
        visit(any, path: [], depth: 0)
        return out
    }

    private static func frame(_ dict: [String: Any], path: [String]) -> Frame? {
        let flat = flatten(dict)
        func find(_ names: Set<String>) -> Any? {
            flat.keys.sorted().first { !Set(tokens($0)).isDisjoint(with: names) }.flatMap { flat[$0] }
        }
        guard let sealedAny = find(["sealed", "ciphertext", "ct", "frame", "wire"]),
              let sealed = bytes(from: sealedAny) else { return nil }
        let dirText = ((find(["dir", "direction", "from", "key"]) as? String) ?? path.joined(separator: "_")).lowercased()
        let toDesktop = dirText.contains("p2d") || dirText.hasPrefix("phone") || dirText.contains("to_desk")
        let counter = (find(["counter", "seq", "n", "nonce"]) as? NSNumber)?.uint64Value ?? 0
        var frame = Frame(toDesktop: toDesktop, counter: counter, sealed: sealed)
        let pt = find(["plaintext", "pt", "json", "message", "msg"])
        if let s = pt as? String { frame.plaintextBytes = Data(s.utf8) }
        else if let obj = pt { frame.plaintextObject = obj }
        return frame
    }
}

struct VectorError: Error, CustomStringConvertible {
    let description: String
    init(_ d: String) { description = d }
}
